import fs from "fs";
import path from "path";
import matter from "gray-matter";

const contentDir = path.join(process.cwd(), "content");

export interface DocMeta {
  slug: string;
  title: string;
  date?: string;
  summary?: string;
  state?: string;
  tag?: string;
}

function readDir(type: "journal" | "work" | "now"): string[] {
  const dir = path.join(contentDir, type);
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".mdx") || f.endsWith(".md"));
}

export function getAllDocs(type: "journal" | "work" | "now"): DocMeta[] {
  return readDir(type)
    .map((file) => {
      const slug = file.replace(/\.mdx?$/, "");
      const raw = fs.readFileSync(path.join(contentDir, type, file), "utf8");
      const { data } = matter(raw);
      return {
        slug,
        title: data.title ?? slug,
        date: data.date,
        summary: data.summary,
        state: data.state,
        tag: data.tag,
      };
    })
    .sort((a, b) => (a.date && b.date ? (a.date < b.date ? 1 : -1) : 0));
}

export function getDoc(type: "journal" | "work" | "now", slug: string) {
  const dir = path.join(contentDir, type);
  const file = path.join(dir, `${slug}.mdx`);
  if (!fs.existsSync(file)) return null;
  const raw = fs.readFileSync(file, "utf8");
  const { data, content } = matter(raw);
  return { meta: data, content };
}

import Link from "next/link";
import Image from "next/image";

const links = [
  { href: "/manifesto", label: "Manifesto" },
  { href: "/journal", label: "Journal" },
  { href: "/work", label: "Work" },
  { href: "/now", label: "Now" },
  { href: "/join", label: "Join" },
];

export function Nav() {
  return (
    <header className="px-6 sm:px-10 pt-8 pb-6">
      <nav className="mx-auto flex max-w-wide items-center justify-between">
        <Link
          href="/"
          className="flex items-center gap-3 group"
          aria-label="The Inner Circle — home"
        >
          <Image
            src="/logo.png"
            alt="The Inner Circle mark"
            width={48}
            height={52}
            priority
            className="opacity-80 group-hover:opacity-100 transition-opacity duration-500"
          />
          <span className="text-sm uppercase tracking-[0.18em] text-ink/80 group-hover:text-accent transition-colors duration-500">
            The Inner Circle
          </span>
        </Link>
        <ul className="flex items-center gap-5 sm:gap-7 text-[0.8rem] tracking-[0.08em] uppercase text-ink/60">
          {links.map((l) => (
            <li key={l.href}>
              <Link
                href={l.href}
                className="hover:text-ink transition-colors duration-500"
              >
                {l.label}
              </Link>
            </li>
          ))}
        </ul>
      </nav>
    </header>
  );
}

export function Footer() {
  return (
    <footer className="px-6 sm:px-10 pt-24 pb-12">
      <div className="mx-auto max-w-wide text-sm text-ink/45 leading-relaxed">
        <p className="max-w-read">
          The Inner Circle is not a product. It is a home for the work that
          happens before anyone notices.
        </p>
        <p className="mt-6 tracking-[0.12em] uppercase text-[0.7rem] text-ink/35">
          The website may evolve. The Constitution does not.
        </p>
      </div>
    </footer>
  );
}

