import fs from "fs";
import path from "path";
import matter from "gray-matter";
import { notFound } from "next/navigation";
import { MDXRemote } from "next-mdx-remote/rsc";
import { FadeIn } from "@/components/FadeIn";
import { getAllDocs } from "@/lib/content";

export function generateStaticParams() {
  return getAllDocs("journal").map((e) => ({ slug: e.slug }));
}

export function generateMetadata({ params }: { params: { slug: string } }) {
  const docs = getAllDocs("journal");
  const doc = docs.find((d) => d.slug === params.slug);
  return { title: doc?.title ?? "Journal", description: doc?.summary };
}

export default function JournalEntry({ params }: { params: { slug: string } }) {
  const file = path.join(process.cwd(), "content", "journal", `${params.slug}.mdx`);
  if (!fs.existsSync(file)) notFound();
  const raw = fs.readFileSync(file, "utf8");
  const { data, content } = matter(raw);

  return (
    <article className="mx-auto max-w-read px-6 sm:px-8 py-10 sm:py-16">
      <FadeIn>
        <p className="text-[0.7rem] uppercase tracking-[0.18em] text-ink/40 mb-4">
          {data.date ?? "Journal"}
        </p>
        <h1 className="text-3xl leading-tight mb-10">{data.title}</h1>
      </FadeIn>
      <FadeIn delay={0.1}>
        <div className="prose-reader">
          <MDXRemote source={content} />
        </div>
      </FadeIn>
    </article>
  );
}

import Link from "next/link";
import { getAllDocs } from "@/lib/content";
import { FadeIn } from "@/components/FadeIn";

export const metadata = {
  title: "Work",
  description:
    "Living work, shown honestly. Witness progress and unfinished thinking — not polished case studies.",
};

export default function WorkPage() {
  const entries = getAllDocs("work");

  return (
    <article className="mx-auto max-w-read px-6 sm:px-8 py-10 sm:py-16">
      <FadeIn>
        <p className="text-[0.8rem] tracking-[0.22em] uppercase text-ink/40 mb-3">
          Work
        </p>
        <p className="prose-reader text-ink/60 mb-12">
          Meaningful work, documented while it is still becoming. Not finished
          achievements.
        </p>
      </FadeIn>

      <div className="space-y-10">
        {entries.map((e, i) => (
          <FadeIn key={e.slug} delay={i * 0.05}>
            <Link href={`/work/${e.slug}`} className="group block">
              <div className="flex items-baseline justify-between gap-4">
                <h2 className="text-2xl leading-snug text-ink group-hover:text-accent transition-colors duration-500">
                  {e.title}
                </h2>
                {e.state && (
                  <span className="shrink-0 text-[0.7rem] uppercase tracking-[0.14em] text-accent/70 border border-accent/30 px-2 py-1">
                    {e.state}
                  </span>
                )}
              </div>
              {e.summary && (
                <p className="mt-3 text-ink/60 leading-relaxed">{e.summary}</p>
              )}
            </Link>
          </FadeIn>
        ))}
      </div>
    </article>
  );
}

