import fs from "fs";
import path from "path";
import matter from "gray-matter";
import { notFound } from "next/navigation";
import { MDXRemote } from "next-mdx-remote/rsc";
import { FadeIn } from "@/components/FadeIn";
import { getAllDocs } from "@/lib/content";

export function generateStaticParams() {
  return getAllDocs("work").map((e) => ({ slug: e.slug }));
}

export function generateMetadata({ params }: { params: { slug: string } }) {
  const docs = getAllDocs("work");
  const doc = docs.find((d) => d.slug === params.slug);
  return { title: doc?.title ?? "Work", description: doc?.summary };
}

export default function WorkEntry({ params }: { params: { slug: string } }) {
  const file = path.join(process.cwd(), "content", "work", `${params.slug}.mdx`);
  if (!fs.existsSync(file)) notFound();
  const raw = fs.readFileSync(file, "utf8");
  const { data, content } = matter(raw);

  return (
    <article className="mx-auto max-w-read px-6 sm:px-8 py-10 sm:py-16">
      <FadeIn>
        <div className="flex items-center gap-3 mb-4">
          <p className="text-[0.7rem] uppercase tracking-[0.18em] text-ink/40">
            {data.date ?? "Work"}
          </p>
          {data.state && (
            <span className="text-[0.7rem] uppercase tracking-[0.14em] text-accent/70 border border-accent/30 px-2 py-1">
              {data.state}
            </span>
          )}
        </div>
        <h1 className="text-3xl leading-tight mb-10">{data.title}</h1>
      </FadeIn>
      <FadeIn delay={0.1}>
        <div className="prose-reader">
          <MDXRemote source={content} />
        </div>
      </FadeIn>
    </article>
  );
}

