import { getAllDocs } from "@/lib/content";
import { SITE } from "@/lib/site";

function esc(s: string) {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export async function GET() {
  // The feed is a notebook, not a news feed: journal and living work, newest first.
  const entries = [
    ...getAllDocs("journal").map((d) => ({ ...d, kind: "Journal" })),
    ...getAllDocs("work").map((d) => ({ ...d, kind: "Work" })),
  ].sort((a, b) => ((a.date ?? "") < (b.date ?? "") ? 1 : -1));

  const items = entries
    .map((e) => {
      const href =
        e.kind === "Journal" ? `${SITE.url}/journal/${e.slug}` : `${SITE.url}/work/${e.slug}`;
      return `    <item>
      <title>${esc(e.title)}</title>
      <link>${href}</link>
      <guid isPermaLink="true">${href}</guid>
      <category>${e.kind}</category>
      ${e.date ? `<pubDate>${new Date(e.date).toUTCString()}</pubDate>` : ""}
      ${e.summary ? `<description>${esc(e.summary)}</description>` : ""}
    </item>`;
    })
    .join("\n");

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${esc(SITE.name)}</title>
    <link>${SITE.url}</link>
    <description>${esc(SITE.description)}</description>
    <language>en</language>
${items}
  </channel>
</rss>`;

  return new Response(xml, {
    headers: { "Content-Type": "application/rss+xml; charset=utf-8" },
  });
}

